def ev(page,loc):return {'source_id':SID,'document_role':'main','pdf_page':page,'printed_page':9432+page,'locator':f'Main PDF p. {page}, printed p. {9432+page}, {loc}'}
def item(sec,key,title,text,page,loc,records=(),scope='source_cohort',kind='reported_source_fact',notes=()):
 assert key not in items
 ee=[ev(page,loc)]
 d={'id':key,'title':title,'text':text,'claim_type':kind,'sample_scope':{'formulations':[],'physical_batch_id':None,'scope_kind':scope,'state':title,'link_limit':SCOPE[scope]},'evidence':ee,'source_locators':[e['locator'] for e in ee],'canonical_links':[{'record_id':P+r,'json_pointer':'','relation':SCOPE[scope]} for r in records],'notes':list(notes),'facts':[],'training_eligible':False}
 items[key]=d;next(s for s in sections if s['id']==sec)['items'].append(d);return d
def add_evidence(key,page,loc):
 e=ev(page,loc);items[key]['evidence'].append(e);items[key]['source_locators'].append(e['locator'])
AG=['ag-'+s for s in 'abcdefghi'];ROUTES=AG+['ir','pt'];PROCEDURES=['ag-typical-framework','recovery','tem-eds','growth-analysis'];OBS=['ag-structure','optical-comparison','solvation','growth-model'];ALL=ROUTES+PROCEDURES+OBS

# Precursors: current materials, analytical solvents, and cited comparisons have separate roles.
item('precursors','chemical-ag','Silver precursor','Silver acetylacetonate, Ag(acac), from Aldrich Chemical Co. is reduced with hydrogen. The typical Ag procedure reports 5.9–16.0 mg, while the nine Table 1 experiments provide separate concentrations and ligand ratios. The mass range is not resolved into individual A–I charges.',2,'Experimental Section, Synthesis',AG+['ag-typical-framework'],scope='method_context')
item('precursors','chemical-ir','Iridium precursor','The reported precursor is (methylcyclopentadienyl)(1,5-cyclooctadiene)iridium(I), supplied by Strem Chemicals. The Ir experiment uses 3.3 mM precursor and a thiol/precursor molar ratio of 7.6:1. No exact weighed charge or Ir-specific stock preparation is reported.',2,'Experimental Section, Synthesis',['ir'],scope='method_context');add_evidence('chemical-ir',4,'Results, iridium and platinum synthesis paragraph')
item('precursors','chemical-pt','Platinum precursor: printed identity','The main article twice names dimethyl(1,5-cyclopentadiene)platinum(II), supplied by Strem Chemicals. Its experiment uses 3.6 mM precursor and thiol/precursor = 6.6:1. The printed ligand name is retained as an unresolved identity issue; a chemically different cyclooctadiene complex is not substituted or drawn as established identity.',2,'Experimental Section, Synthesis',['pt'],scope='method_context',notes=['An authoritative molecular structure for the printed Pt precursor has not been established from this source.']);add_evidence('chemical-pt',4,'Results, iridium and platinum synthesis paragraph')
item('precursors','chemical-ligand','Surface ligand: partially fluorinated octanethiol','The stabilizer is 1H,1H,2H,2H-perfluorooctanethiol, C₆F₁₃C₂H₄SH, from Oakwood Products. Its eight-carbon chain contains six fluorinated carbons and two hydrocarbon carbons adjacent to thiol. The typical Ag experiment uses 162–324 mg. This C8 ligand differs from the C10 ligand in the cited Ag comparison.',2,'Experimental Section, Synthesis',ROUTES+['ag-typical-framework'],scope='method_context')
item('precursors','chemical-co2','Carbon dioxide: reaction medium and pressure fluid','CO₂ from Matheson Gas Products has stated purity >99.99% and is used as received. The typical procedure loads 14–18 mL at 138 bar and 20 °C; CO₂ behind the piston subsequently applies the 276 bar reaction pressure. The initial fill volume and the cell working volume are distinct quantities.',2,'Experimental Section, Synthesis',ROUTES+['ag-typical-framework'],scope='method_context')
item('precursors','chemical-h2','Hydrogen: reducing agent','Hydrogen from Praxair has stated purity >99.999% and is used as received. The typical experiment introduces 6.22 mg simultaneously with the thiol. Figure 1 labels an 800 µL hydrogen injection loop; the hardware volume is not a gas volume at standard conditions.',2,'Experimental Section and Figure 1',ROUTES+['ag-typical-framework'],scope='method_context')
item('precursors','chemical-acetone','Acetone: product collection and redispersion','Omnisolv spectrophotometry-grade acetone from EM Science collects particles from the depressurized cell. After heptane precipitation, particles are redispersed in acetone for analysis. Recovery and analytical dispersion volumes are not stated.',2,'Experimental Section, recovery paragraph',['recovery'],scope='method_context')
item('precursors','chemical-heptane','Heptane: antisolvent','Heptane precipitates the nanocrystals from the collection dispersion. The authors state that unreacted precursor, unbound ligand and unwanted byproducts remain in the supernatant. Heptane amount, grade, addition rate and solid–liquid separation settings are not reported.',2,'Experimental Section, recovery paragraph',['recovery'],scope='method_context')
item('precursors','chemical-other-solvents','Additional redispersion solvents','The collected particles also disperse in Fluorinert brand electronic liquid and 1,1,2-trichlorotrifluoroethane, called Freon in the article. Fluorinert is a trade-name liquid with no composition specified here; it is not assigned a single molecular formula. Ethanol appears later in solvation reasoning, without an explicitly quantified redispersion experiment.',2,'Experimental Section, final synthesis paragraph',['solvation'],notes=['Distinct from the water/acetone, water/chloroform and hexane media of the Figure 7 comparison.']);add_evidence('chemical-other-solvents',5,'Discussion, ligand solvation paragraph')
item('precursors','chemical-comparators','Cited optical-comparison reagents','Figure 7 compares the present Ag(acac)/C₆F₁₃C₂H₄SH route with AgNO₃ reduction in water/acetone using C₈F₁₇C₂H₄SH, and a water/chloroform biphasic AgNO₃ route using dodecanethiol, C₁₂H₂₅SH. The comparison samples are dispersed in acetone and hexane, respectively. These captions do not supply complete new synthesis recipes.',4,'Figure 7 caption',['optical-comparison'],scope='cited_context')
item('precursors','stocks-unreported','Stocks and absolute quantities','No separately prepared precursor stock or quantitatively specified ligand solution is reported. Table 1 concentrations and molar ratios remain the formulation definitions for A–I. The typical cell volume, filling volume and mass ranges do not establish the exact reaction volume or charge of each row.',2,'Experimental Section and Table 1',['ag-typical-framework']+AG,scope='curator_interpretation',kind='reviewed_source_limitation')

# Protocol: sequential operations preserve measured conditions and missing details.
item('protocol','apparatus','Variable-volume high-pressure apparatus','All reactions use a temperature-controlled stainless-steel view cell with a piston, a front sapphire window and 1.75 cm internal diameter. The typical working volume with the piston in place is 27 mL. This is a pressure-cell synthesis, with Figure 1 documenting the plumbing and injection loops.',2,'Experimental Section and Figure 1',['ag-typical-framework'],scope='method_context')
item('protocol','charge-ag','Charge the silver precursor','Load 5.9–16.0 mg Ag(acac) in the reaction cell for the reported typical Ag framework. Individual experiments are specified by Table 1 concentrations, not by row-specific weighed masses. These absolute Ag charges are not transferred to Ir or Pt.',2,'Experimental Section, typical experiment',['ag-typical-framework'],scope='method_context')
item('protocol','fill-co2','Fill the sealed cell with carbon dioxide','Seal the cell and introduce 14–18 mL CO₂ at 138 bar and 20 °C. These are the filling conditions, preceding heating and the final 276 bar pressure. The source does not state an evacuation cycle, purge count or a final fluid volume for every experiment.',2,'Experimental Section, typical experiment',['ag-typical-framework'],scope='method_context')
item('protocol','pressurize','Apply pressure through the piston','Use CO₂ on the back side of the piston and a Dionex model 501 Computer Controlled Syringe Pump to reach 276 bar. The pressure is held constant during reaction. The source does not state a numerical pressure tolerance or pressure-ramp rate.',2,'Experimental Section, typical experiment',['ag-typical-framework']+ROUTES,scope='method_context')
item('protocol','heat','Heat before reduction','Heat to the chosen reaction temperature with heating tape connected to an Omega CN76000 controller. A thermocouple inserted in the cell verifies reaction temperature. Ag temperatures span 60–100 °C; both Ir and Pt are reacted at 80 °C. The precursor is reported not to decompose at this stage before hydrogen addition.',2,'Experimental Section, typical experiment',['ag-typical-framework']+ROUTES,scope='method_context');add_evidence('heat',4,'Results, Ir/Pt reaction conditions')
item('protocol','simultaneous-injection','Introduce hydrogen and ligand simultaneously','The typical Ag procedure introduces 162–324 mg fluorinated thiol and 6.22 mg H₂ together using a high-pressure injection pump and two six-port Valco rotary valves in series. Attached sample loops are labeled 100/200 µL for thiol and 800 µL for hydrogen in Figure 1. Injection duration, flow rate and mixing speed are not given.',2,'Experimental Section and Figure 1',['ag-typical-framework'],scope='method_context')
item('protocol','reaction-dwell','React for three hours','The reported reaction interval is 3 h, selected by the authors to ensure completion. The cell appears darkest after approximately 1 h. This visual observation is retained as a separate observation and does not replace the dwell or prove quantitative precursor conversion.',2,'Experimental Section, typical experiment',['ag-typical-framework'],scope='method_context')
item('protocol','cool-vent','Cool, depressurize and vent','Cool the cell to room temperature, depressurize, and vent CO₂ as vapor from the top. The authors state that most components other than H₂ remain in the cell. Cooling time, numerical endpoint, depressurization rate and venting profile are unreported.',2,'Experimental Section, recovery sequence',['recovery'],scope='method_context')
item('protocol','collect','Collect the particles in acetone','Use spectrophotometry-grade acetone to collect the nanocrystals from the cell. The source supplies neither collection-solvent volume nor a quantified recovery yield.',2,'Experimental Section, recovery sequence',['recovery'],scope='method_context')
item('protocol','precipitate','Precipitate with heptane','Add heptane as antisolvent to separate nanocrystals from unreacted precursor, unbound capping ligands and byproducts remaining in the supernatant. Centrifugation speed, duration, wash count, solvent ratio and isolated mass are not reported.',2,'Experimental Section, recovery sequence',['recovery'],scope='method_context')
item('protocol','redisperse','Redisperse the isolated particles','Redisperse the particles in acetone for analysis; fluorinated-solvent redispersion is also reported. The article does not specify a final powder-drying operation. After collection and washing, the C8-ligand particles do not redisperse in pure CO₂, despite stability during synthesis.',2,'Experimental Section, recovery sequence',['recovery','solvation'],scope='method_context');add_evidence('redisperse',5,'Discussion, ligand-chain length and redispersibility')
TABLE=[('A',1.8,14.9,60,39,18,46),('B',2.2,10.3,90,26,11,45),('C',2.9,8.2,70,50,23,45),('D',3.4,6.0,80,57,33,57),('E',3.4,5.7,90,55,27,49),('F',3.4,6.0,100,59,31,52),('G',3.6,5.8,70,56,22,40),('H',3.9,6.4,70,69,34,49),('I',4.9,11.0,70,107,40,38)]
for label,conc,ratio,temp,diam,sd,pct in TABLE:
 item('protocol','table1-'+label.lower(),f'Ag experiment {label}',f'Table 1 pairs {conc:g} mM precursor, thiol/precursor = {ratio:g}:1 (mol/mol), and {temp} °C with a mean nanocrystal diameter of {diam} Å, standard deviation {sd} Å and reported relative standard deviation {pct}%. Figure 5 panel {label} supplies its original diameter histogram. The reported percentage is retained rather than recalculated from rounded diameter values.',2,f'Table 1, row {label}',['ag-'+label.lower()],notes=['Pressure is 276 bar by the shared method. Typical absolute charges cannot be assigned to this row.'])
 add_evidence('table1-'+label.lower(),4,'Figure 5, panel '+label)
item('protocol','ir-route','Iridium formulation','The Ir experiment uses 3.3 mM (methylcyclopentadienyl)(1,5-cyclooctadiene)iridium(I), thiol/precursor = 7.6:1, 80 °C and 276 bar. Figure 8a is the corresponding material-specific TEM evidence. No individual Ir mass, exact mean diameter or distribution table is provided.',4,'Results, Ir/Pt synthesis and Figure 8 association',['ir'])
item('protocol','pt-route','Platinum formulation','The Pt experiment uses 3.6 mM of the precursor named dimethyl(1,5-cyclopentadiene)platinum(II), thiol/precursor = 6.6:1, 80 °C and 276 bar. Figure 8b provides TEM evidence. The precursor-name ambiguity remains visible, and an exact mean diameter or row-specific charge is not inferred.',4,'Results, Ir/Pt synthesis and Figure 8 association',['pt'])
item('protocol','tem-acquisition','TEM acquisition','A JEOL 2010 high-resolution transmission electron microscope operates at 200 kV with stated 1.7 Å point-to-point resolution and GATAN digital photography. Nanocrystals are deposited on 200-mesh carbon-coated copper grids. Dispersion concentration, deposition volume, grid drying and image dose are not specified.',2,'Experimental Section, Characterization',['tem-eds'],scope='method_context')
item('protocol','size-analysis','Particle-size analysis','Scion Image for Windows is used to determine particle diameters and distributions. At least 400 nanocrystals are measured per sample. Exact counts and raw particle-by-particle data are not supplied. Later volume-distribution analysis assumes spherical particles when transforming TEM diameters.',2,'Experimental Section, Characterization',['tem-eds','growth-analysis'],scope='method_context');add_evidence('size-analysis',5,'Discussion, nondimensional distribution analysis')
item('protocol','eds-acquisition','Energy-dispersive X-ray acquisition','EDS is performed in situ on a JEOL 2010 TEM equipped with an Oxford Link ISIS instrument. The source does not report detector calibration, acquisition time, quantified elemental fractions or an independent background subtraction protocol.',2,'Experimental Section, Characterization',['tem-eds'],scope='method_context')

# Structural images and quantitative distributions.
item('structures','ag-tem','Ag morphology and surface separation','Figure 2a is a representative TEM image of fluorinated-thiol-coated Ag particles with a 50 nm scale bar. The authors report approximately 20 Å interparticle separation and attribute colloidal stability to tightly bound organic ligands. No experiment A–I is uniquely assigned to this image.',3,'Figure 2a and Results',['ag-structure'])
item('structures','ag-packing','Particle-array order','Figure 2b, with a 40 nm scale bar, shows extended hexagonally close-packed particle arrays without size fractionation despite a broad size distribution. This describes positional ordering of whole nanocrystals; it is not a claim of an HCP atomic phase of silver.',2,'Results, Figure 2 discussion',['ag-structure']);add_evidence('ag-packing',3,'Figure 2b and caption')
item('structures','ag-lattice','Crystalline silver cores','Figure 2c is HRTEM with a 5 nm scale bar. The text assigns visible fringes to silver {111} planes. No numerical lattice spacing, refined unit cell, indexed diffraction pattern or atomic coordinates are supplied.',2,'Results, Figure 2c discussion',['ag-structure']);add_evidence('ag-lattice',3,'Figure 2c and caption')
item('structures','ag-diameter-range','Silver diameter and dispersity scope','The tabulated Ag mean diameters range from 26 to 107 Å, with relative standard deviations from 38% to 57%. The article summarizes dispersity as approximately 47%. The abstract’s 20–120 Å range covers the reported Ag/Ir/Pt study and does not replace the paired Ag rows or provide individual Ir/Pt distributions.',2,'Table 1 and Results',AG+['ag-structure']);add_evidence('ag-diameter-range',1,'Abstract')
item('structures','ag-concentration-trend','Diameter versus precursor concentration','Figure 3 plots mean Ag diameter against initial precursor concentration for the Table 1 experiments. Error bars describe sample polydispersity, not uncertainty in the size-measurement technique. Symbol shapes distinguish 60, 70, 80, 90 and 100 °C. The authors observe an overall increase in size with precursor loading; the small, multivariable set is not a continuous predictive calibration.',3,'Figure 3 and caption',AG+['growth-analysis'])
item('structures','ag-temperature-trend','Temperature comparison and figure ambiguity','Figure 4 is captioned experiments D–G and reports little temperature dependence at approximately comparable concentrations and ligand ratios. The image contains five points, including two at 70 °C, while D–G comprises four table rows. The extra point remains unassigned; matching its appearance to row H would be an inference. Error bars are polydispersity.',3,'Figure 4 and caption',['growth-analysis']+[f'ag-{s}' for s in 'defg'],scope='curator_interpretation',kind='source_evidence_conflict')
item('structures','ag-histograms','Nine original diameter distributions','Figure 5 panels A–I preserve the experimentally measured Ag diameter histograms for their corresponding Table 1 rows. Diameter is in Å; the vertical axis is frequency without printed numerical frequency values. Each panel spans 0–200 Å. Raw individual diameters, exact bin boundaries and numerical bin counts are not supplied.',4,'Figure 5',AG+['growth-analysis'])
item('structures','ag-eds','Elemental evidence','Figure 6 is an EDS spectrum with energy in keV and counts on the vertical axis. It labels carbon, fluorine, sulfur and silver peaks, supporting the presence of the metal and fluorinated thiol. It is not a quantitative ligand-coverage measurement or proof of phase purity; the specimen support is carbon-coated copper.',3,'Results, EDS discussion',['ag-structure','tem-eds']);add_evidence('ag-eds',4,'Figure 6')
item('structures','ir-tem','Iridium nanocrystals','Figure 8a shows C₆F₁₃C₂H₄SH-coated iridium nanocrystals with a 10 nm scale bar and a 5 nm inset bar. The authors describe crystalline cores. The image is linked to the Ir material experiment, with no exact particle-by-particle diameter table, refined phase or unit cell supplied.',6,'Figure 8a and caption',['ir'])
item('structures','pt-tem','Platinum nanocrystals','Figure 8b shows C₆F₁₃C₂H₄SH-coated platinum nanocrystals with a 10 nm scale bar. The text describes crystalline cores. A mean diameter, relative width, quantitative surface coverage and atomic-coordinate model are not supplied for this cohort.',6,'Figure 8b and caption',['pt'])
item('structures','ag-polycrystals','Internal grain boundaries','Figure 11a–c shows multiple misaligned lattice fringes within Ag cores, each panel with a 5 nm scale bar. Figure 11d, with a 6 nm bar, is described as a coagulated particle with partial realignment of crystal planes. The images support the authors’ growth interpretation but are not uniquely mapped to A–I.',7,'Figure 11 and caption',['ag-structure','growth-analysis'])
item('structures','ag-majority-single','Single- and polycrystalline particles','The text states that most examined particles appear single crystalline, while some preserve polycrystalline domains. The authors suggest post-coagulation lattice rearrangement as an explanation. Neither the fraction of polycrystalline particles nor a time-resolved sequence is provided.',6,'Discussion, Figure 11 interpretation',['ag-structure','growth-model'])
item('structures','structural-limitations','Atomic structure and diffraction coverage','The supplied article contains TEM/HRTEM and EDS, but no XRD pattern, SAED pattern, refined lattice parameters, CIF, VESTA file or measured ligand binding geometry. Any future downloadable bulk reference structure must be clearly distinguished from these source-specific nanocrystals.',7,'Figure 11; complete main-article review',['ag-structure','ir','pt'],scope='curator_interpretation',kind='reviewed_source_limitation')

# Properties: explicit specimen and solvent identities prevent spurious training joins.
item('properties','optical-current','Current CO₂-synthesized silver: spectrum i','Figure 7(i) is Ag from Ag(acac) reduction in sc-CO₂ with C₆F₁₃C₂H₄SH, measured as an acetone dispersion. The authors describe its mean diameter as 59 Å and its characteristic surface-plasmon absorbance maximum as 400 nm. Although Table 1F also has a 59 Å mean, the optical sample is not explicitly identified as experiment F.',3,'Results, surface-plasmon discussion',['optical-comparison']);add_evidence('optical-current',4,'Figure 7(i), caption and Results')
item('properties','optical-c10','C10-ligand comparison: spectrum ii','Figure 7(ii) represents AgNO₃ reduction in water/acetone with C₈F₁₇C₂H₄SH, measured in acetone. The text reports a 55 Å mean diameter and cites Shah et al. (2000), reference 23. This comparison differs from the present route in precursor, solvent system, ligand length and particle size.',4,'Figure 7(ii), caption and Results',['optical-comparison'],scope='cited_context')
item('properties','optical-hydrocarbon','Hydrocarbon-ligand comparison: spectrum iii','Figure 7(iii) is dodecanethiol-capped Ag from AgNO₃ reduction in water/chloroform, measured in hexane. Its size is described as approximately comparable, without an exact mean specified here. Its absorption peak is narrower than those of the fluorocarbon-coated samples.',4,'Figure 7(iii), caption and Results',['optical-comparison'],scope='cited_context')
item('properties','optical-measurement-scope','Spectral units and measurement limits','The original Figure 7 plot spans 325–575 nm and labels absorbance in arbitrary units. No raw numerical spectrum, absolute extinction coefficient, fitted linewidth, optical instrument, cuvette path length or concentration is supplied. The article provides no PL, Raman, electrical, catalytic or magnetic measurement for these samples.',4,'Figure 7 and complete main-article review',['optical-comparison'],scope='curator_interpretation',kind='reviewed_source_limitation')
item('properties','optical-width-interpretation','Ligand-dependent plasmon broadening','The authors relate the difference between the two fluorinated-ligand spectra partly to their 55 versus 59 Å sizes. They propose that the high electronegativity of fluorinated groups shortens the electron mean free path, contributing to broader absorption than hydrocarbon-coated particles. This is an interpretation, not a measured electron transport parameter.',4,'Results, optical comparison paragraph',['optical-comparison','growth-model'],scope='model_context',kind='author_interpretation')
item('properties','dispersibility','Dispersibility after recovery','Repeated redispersion in acetone and fluorinated solvents is reported. The current C₆F₁₃C₂H₄SH-coated particles remain stable during synthesis but, after collection and washing, cannot be redispersed in pure CO₂. This difference between synthesis stability and post-isolation redispersibility is retained as an experimental outcome.',5,'Discussion, Steric Stabilization in CO₂',['solvation'])
item('properties','spacing-comparison','Interparticle separation comparison','Current fluorocarbon-coated Ag particles show approximately 20 Å edge-to-edge separation in TEM; the cited octanethiol-coated comparison is approximately 10 Å. The authors connect the greater separation to more rigid fluorocarbon monolayers. These are source-level comparisons, not paired distances measured on all Table 1 rows.',3,'Results, ligand spacing discussion',['ag-structure','solvation'])

# Chemical intuition: distinguish source explanations, theoretical values and outlook.
item('intuition','why-arrested','Arrested precipitation and surface passivation','The synthesis combines precursor reduction, metal nucleation and growth with adsorption of thiolate ligands. Adsorbed chains provide a steric barrier and eventually arrest growth. The article frames this as a single CO₂-phase method, unlike the earlier water-in-CO₂ microemulsion examples cited in references 20 and 21.',1,'Introduction',['growth-model'],scope='model_context',kind='author_interpretation')
item('intuition','why-supercritical','Why a supercritical medium?','The authors emphasize liquid-like solvent density together with lower viscosity and higher diffusivity, and the possibility of adjusting solvation by pressure and temperature. References 4–12 provide the cited theory, simulation and scattering context. Density-controlled reversible colloidal stabilization, separation and assembly are motivations, not demonstrated quantitative pressure sweeps in this article.',1,'Introduction, supercritical-fluid context',['growth-model'],scope='cited_context')
item('intuition','why-fluorinated','Why partially fluorinated thiol?','CO₂ has low polarizability and weak dispersion interactions, so suitable CO₂-solvated tails are needed for steric stabilization. The thiol group binds the metal while the fluorinated segment interacts with CO₂. The source contrasts bound capping molecules with microemulsion surfactants that can permit irreversible aggregation during recovery.',1,'Introduction, CO₂-compatible ligands and prior systems',['growth-model'],scope='model_context',kind='author_interpretation')
item('intuition','why-hydrogen','Hydrogen reduction at moderate temperature','The authors attribute reduction at 60–100 °C, compared with approximately 140 °C in a cited metal-film CVD example, to high hydrogen and organometallic-precursor solubility in CO₂. This cited comparison is not a measured activation energy or a universal temperature requirement.',2,'Results, precursor reduction and references 27–29',['growth-model'],scope='model_context',kind='author_interpretation')
item('intuition','thiol-excess','Why a large ligand excess?','High thiol/precursor ratios are intended to promote surface coverage in a challenging solvent. The authors observe little size effect over their tested range but explicitly state that a more intensive study would be needed to resolve ligand-ratio effects. Table 1 values, rather than a universal optimal ratio, define the formulations.',3,'Results, thiol/precursor discussion',['growth-model'],scope='model_context',kind='author_interpretation')
item('intuition','note32-context','Note 32: prior ligand-ratio comparisons','Note 32 cites prior biphasic systems with thiol/precursor <1, Brust gold particles of 10–30 Å with a final thiol/gold ratio of 1:3, and Leff’s thermodynamic size control at thiol/precursor ratios from 1:1 to 6:1. These distinct literature quantities explain the authors’ use of excess thiol; they are not additional current recipes or interchangeable ratios.',8,'Note 32',['growth-model'],scope='cited_context')
item('intuition','ligand-rigidity','Ligand-shell rigidity and spacing','The authors invoke the bulkiness of fluorine and the reported rigidity of fluorocarbon monolayers to explain why coated particles remain farther apart than hydrocarbon-coated comparisons. The source supplies no measured elastic modulus, molecular dynamics trajectory or resolved surface conformation.',3,'Results, interparticle spacing and reference 33',['growth-model','solvation'],scope='model_context',kind='author_interpretation')
item('intuition','equation-1','Core–core attraction','Equation 1 describes the van der Waals interaction between equal-radius particles with radius R and edge-to-edge separation d. The Hamaker constant A sets the interaction strength. The original equation is retained as theory; it is not a fitted force-distance curve for these particles.',4,'Discussion, Equation 1',['growth-model'],scope='model_context',kind='author_theoretical_model')
item('intuition','equation-2','Estimating the Hamaker constant','Equation 2 is a simplified Lifshitz estimate using dielectric constants and refractive indices of particles (subscript 1) and medium (2), temperature, Planck’s constant and an assumed electronic ultraviolet frequency. The stated typical frequency is 3 × 10¹⁵ s⁻¹. Vacuum is modeled with ε₂ = n₂ = 1; the source uses a bulk-Ag vacuum value of 2.2 eV despite noting nanoparticle size dependence.',5,'Discussion, Equation 2 and definitions',['growth-model'],scope='model_context',kind='author_theoretical_model')
item('intuition','equation-3','Combining medium and particle interactions','Equation 3 estimates A₁₃₁ ≈ (√A₁₁ − √A₃₃)², where A₁₃₁ is for silver cores across CO₂, A₁₁ for silver across vacuum and A₃₃ for CO₂ across vacuum. The paper calculates 1.4 eV for Ag in its CO₂ context versus 0.93 eV in acetone, described as nearly 50% stronger attraction. These are model estimates, not measured sample properties.',5,'Discussion, Equation 3 and Hamaker comparison',['growth-model'],scope='model_context',kind='author_theoretical_model')
item('intuition','chain-length','Chain length and the distinction between growth control and redispersion','The current C8 ligand controls growth but does not enable redispersion in pure CO₂ after washing. The prior C10 ligand, C₈F₁₇C₂H₄SH in reference 23, does enable CO₂ dispersion. The authors reason that CO₂ mainly solvates the fluorinated segment, so the shorter shell cannot keep cores sufficiently separated after isolation.',5,'Discussion, C8/C10 ligand comparison',['solvation','growth-model'],scope='model_context',kind='author_interpretation')
item('intuition','polar-solvation','Solvation in polar solvents','The source proposes that acetone and ethanol can interact with the CH₂–CF₂ segment through dipolar interactions, allowing more of the ligand chain to contribute to stabilization. The analogy to short hexanethiol shells and the external fluorine-chemistry reference are contextual reasoning, not quantitatively measured solvation energies.',5,'Discussion, ligand-tail solvation and reference 39',['solvation','growth-model'],scope='model_context',kind='author_interpretation')
item('intuition','nucleation-growth','Nucleation, growth and passivation','The authors describe H₂-driven production of metal atoms, nucleation as supersaturation is relieved, growth by atom condensation or core fusion, and eventual passivation. Temporal separation of nucleation and growth is invoked as a route to narrow distributions. These mechanistic explanations cite references 3 and 40–42; no direct metal-atom concentration or nucleation-rate trace is reported here.',5,'Discussion, Growth Mechanism',['growth-model'],scope='model_context',kind='author_interpretation')
item('intuition','scaled-distributions','Scaled particle-volume distributions','For the Ag TEM data, diameters are converted to volumes assuming spheres. The authors define ψ₁(η) = n(v)φ/N∞², N∞ = ∫n(v)dv, φ = ∫v n(v)dv and η = vN∞/φ. Figure 9 compares all A–I distributions in this reduced representation; the reported similarity is interpreted as a common growth mechanism across precursor concentrations.',5,'Discussion, nondimensional distribution definitions and Figure 9 association',['growth-analysis','growth-model'],scope='model_context',kind='reported_derived_observation');add_evidence('scaled-distributions',6,'Figure 9')
item('intuition','coagulation-condensation','Coagulation versus condensation','The paper contrasts narrowing by diffusion-limited atom condensation with broadening by particle coagulation. Its broad, approximately log-normal Ag size distributions and approximately 47% relative dispersion motivate a coagulation-dominated interpretation. This does not establish that atom condensation never occurs.',5,'Discussion, end of Growth Mechanism',['growth-model'],scope='model_context',kind='author_interpretation');add_evidence('coagulation-condensation',6,'Discussion continuation')
item('intuition','moment-ratios','Distribution moments and mean-radius definitions','The source defines μ₁ = r₃/rₕ and μ₃ = r₁/r₃, with arithmetic mean radius r₁, cube-mean radius r₃ and harmonic mean radius rₕ. Their reported averages are 1.48 and 0.82. The cited coagulation criteria are μ₁ >1.25 and μ₃ <0.905; a monodisperse distribution has all three radii equal and both ratios equal to 1. These are distribution-level statistics, not nine extra synthesis outcomes.',6,'Discussion, moment definitions',['growth-analysis','growth-model'],scope='model_context',kind='reported_derived_observation')
item('intuition','cumulative-distribution','Cumulative distributions and the Brownian model','Figure 10 compares ψ₂(η), the fraction of particles larger than volume v, for A–I with a theoretical Brownian coagulation curve at long times and sticking probability 1. The original cumulative integral notation is retained in an equation excerpt. The modest deviation in the middle of the distribution is interpreted as ligand-modulated sticking below 1, tending toward zero as stable particles become passivated.',6,'Discussion, cumulative distribution and Figure 10',['growth-analysis','growth-model'],scope='model_context',kind='author_interpretation',notes=['No numerical time-dependent sticking probability or fitted rate constant is reported.'])
item('intuition','coagulation-structure','Structural evidence and rearrangement after fusion','Polycrystalline domains in Figure 11 may preserve signs of early nuclei joining. The prevalence of apparently single-crystal particles is interpreted as subsequent plane realignment. The comparison to reorganization in gold particles up to 70 Å is a personal communication (reference 48), not an independently reviewed gold synthesis or a direct Ag time-resolved measurement.',6,'Discussion, Figure 11 interpretation and reference 48',['growth-model','ag-structure'],scope='model_context',kind='author_interpretation')
item('intuition','outlook','Precursor and ligand design outlook','The authors propose extending the approach to CO₂-soluble precursors that remain stable at moderate temperature but decompose rapidly when H₂ is added. Higher temperatures or stronger reducing agents may be needed when H₂ is ineffective. Suitable ligands must bind strongly enough to arrest growth while permitting growth, and have tails sufficiently solvated to prevent irreversible aggregation. These are prospective design criteria.',7,'Conclusions',['growth-model'],scope='author_outlook',kind='author_outlook')
item('intuition','environmental-context','Solvent motivation and scope','The paper motivates CO₂ as a nonflammable, low-critical-temperature alternative to conventional solvents and describes it as environmentally benign. This source-level motivation is separate from the full process, which also uses high pressure, hydrogen, organometallic precursors and fluorinated reagents; no life-cycle assessment or solvent comparison experiment is supplied.',1,'Introduction, CO₂ motivation',['growth-model'],scope='cited_context')

# Coverage, scientific conflicts and bibliography.
item('sources','identity','Source identity','Parag S. Shah, Shabbir Husain, Keith P. Johnston and Brian A. Korgel, “Nanocrystal Arrested Precipitation in Supercritical Carbon Dioxide,” Journal of Physical Chemistry B 2001, 105(39), 9433–9440; DOI 10.1021/jp011815c. Received May 11, 2001; published online August 31, 2001. The local eight-page main article is the directly inspected source.',1,'Title, byline, dates and journal footer',scope='source_metadata',kind='source_metadata')
item('sources','review-coverage','Main text and supporting information','All eight supplied main-article pages have been read and visually inspected, including 11 figures, Table 1, three numbered equations, the unnumbered distribution definitions and all 48 references/notes. No supporting-information file has been located and matched in this task. That status does not prove that no SI exists.',8,'Complete supplied main article',scope='source_metadata',kind='reviewed_source_limitation')
item('sources','identity-affiliation','Affiliation and document dates','The authors are affiliated with the Department of Chemical Engineering and Texas Materials Institute, Center for Nano- and Molecular Science and Technology, University of Texas at Austin. Johnston and Korgel are corresponding authors. The institutional-download watermark dated July 7, 2026 is neither a publication date nor an experiment date.',1,'Affiliation, corresponding-author note and download watermark',scope='source_metadata',kind='source_metadata')
item('intuition','background-properties','Size-dependent properties as motivation','The introduction discusses nanocrystals around 20–100 Å with size-dependent optical, catalytic, magnetic and electronic properties and possible coating, environmental, processing, medical, electronic and sensing applications. These are cited motivations from references 1–3; the present article does not measure all of those properties.',1,'Introduction, opening paragraph',scope='cited_context')
item('intuition','prior-film-deposition','Related thin-film deposition','References 24–26 describe hydrogen reduction of organometallic precursors in CO₂ to produce uniform thin metal films. This prior deposition work motivates the reaction chemistry but is not a nanoparticle formulation in the present dataset.',1,'Introduction, final paragraph',scope='cited_context')
item('sources','historical-claim','Historical scope of the authors’ claim','The authors describe their route as the first arrested-precipitation synthesis of sterically stabilized monolayer-protected nanocrystals directly in CO₂. This historical claim is attributed to the 2001 paper; it is not an independently established current novelty assessment.',1,'Introduction, first-use statement',scope='cited_context',kind='attributed_historical_claim');add_evidence('historical-claim',7,'Conclusions, first-synthesis statement')
items['chemical-ag']['notes'].append('Metal precursors and ligand are purchased; this source gives no upstream precursor synthesis or purification and no reagent purities other than the gases.')
items['why-fluorinated']['text']+=' Fluoroacrylates, alkanes and ethers are cited examples of compatible surfactant classes, not additional reagents used here.'
items['ag-concentration-trend']['text']+=' The concentration axis spans 0–6 mM and diameter 0–175 Å; 60, 70, 80, 90 and 100 °C use square, circle, downward triangle, diamond and upward triangle symbols, respectively. The prose summarizes a roughly twofold precursor-loading change.'
items['ag-temperature-trend']['text']+=' The original axes span 60–110 °C and 0–150 Å.'
items['equation-2']['notes'].append('The source prints electronic ultraviolet adsorption frequency; this terminology is retained as source wording, not silently converted into a measured absorption peak.')
items['scaled-distributions']['text']+=' Both axes are logarithmic: η spans 0.001–100 and ψ₁ spans 0.0001–1. The long-time self-preserving argument is theory; the experiments compare endpoint distributions rather than a time-resolved evolution.'
items['cumulative-distribution']['text']+=' Figure 10 uses logarithmic η from 0.001 to 100 and linear ψ₂ from 0 to 1.2; symbols are data-derived distributions and the solid line is theory.'
item('sources','sample-boundaries','Formulations, procedures and observations','Experiments A–I are nine paired Ag formulations; the Ir and Pt conditions supply two additional material routes. The typical Ag framework, recovery, TEM/EDS and distribution-analysis procedures are supporting records. Unassigned Ag TEM, EDS, optical and solvation contexts do not gain a Table 1 batch identity by matching one size or sharing a material name.',2,'Table 1, methods and figure associations',ALL,scope='curator_interpretation',kind='curation_scope')
item('sources','conflict-size','Diameter-range wording','The Results prose once says that the mean diameter rises from 25 to 107 Å, while Table 1B and the Conclusions give 26 Å as the minimum tabulated mean. The canonical paired row retains 26 Å; the discrepant prose is preserved as a source conflict.',2,'Table 1 and Results concentration discussion',['ag-b','ag-structure'],scope='curator_interpretation',kind='source_evidence_conflict');add_evidence('conflict-size',7,'Conclusions')
item('sources','conflict-thiol','Ligand-ratio wording','The prose summarizes thiol/precursor as 6:1 to 15:1, whereas Table 1 explicitly includes 5.7:1 and 5.8:1 and a maximum 14.9:1. The exact row values take precedence for formulation records; the prose range remains an approximate summary.',3,'Results, thiol-ratio discussion',['ag-e','ag-g','ag-a'],scope='curator_interpretation',kind='source_evidence_conflict');add_evidence('conflict-thiol',2,'Table 1')
item('sources','conflict-temperature','CO₂-state wording in the model','The introduction prints a CO₂ critical temperature of 31 °C and critical pressure of 71 bar. Later, the Hamaker discussion uses the phrase sc-CO₂ at 25 °C. The model context is retained with this inconsistency visible; the 25 °C value is not labeled as a verified supercritical state or used as a synthesis condition.',5,'Discussion, Hamaker constant comparison',['growth-model'],scope='curator_interpretation',kind='source_evidence_conflict');add_evidence('conflict-temperature',1,'Introduction, critical parameters')
item('sources','conflict-chain','Fluorinated-segment length comparison','The paper calls the fluorinated segment 20% shorter in the C8 ligand than in the C10 ligand. Their printed formulas specify six versus eight fluorinated carbons; 20% instead matches the change in total carbons from ten to eight. The formulas and the source wording remain distinct, without silently correcting the source’s percentage.',5,'Discussion, perfluorocarbon-chain comparison',['solvation','growth-model'],scope='curator_interpretation',kind='source_evidence_conflict')
item('sources','conflict-integral','Cumulative-integral notation','The printed cumulative relation uses ψ₂(η) = Nᵥ/N∞ = ∫η∞ψ₁(η)dv, mixing a dimensionless integration limit and integrand notation with dv. The original crop preserves what was printed. It is explanatory source theory, not executable numerical code; no implicit correction is used to generate data.',6,'Discussion, cumulative distribution definition',['growth-model','growth-analysis'],scope='curator_interpretation',kind='source_evidence_conflict')
item('sources','unreported-details','Unreported experimental fields','The source does not supply row-specific absolute charges, final reaction-fluid volumes, injection duration, mixing speed, heating/cooling ramps, gas-flow rates, venting rate, solvent volumes, separation settings, yields, raw particle lists or complete optical acquisition conditions. These fields remain unknown. Methods from cited papers are not filled in without separate review.',2,'Experimental Section and complete main-article review',scope='curator_interpretation',kind='reviewed_source_limitation')
item('sources','acknowledgments','Research support and TEM assistance','The acknowledgments identify NSF STC agreement CHE-9876674, the Petroleum Research Fund, Welch Foundation, UT Austin Separations Research Program and DuPont young-professor support. John Mendenhall is thanked for TEM assistance. This is source provenance, not synthesis evidence.',7,'Acknowledgments',scope='source_metadata',kind='source_metadata');add_evidence('acknowledgments',8,'Acknowledgments continuation')

